package com.franco.desco.adapter.out.sqlserver.property;

import com.franco.desco.adapter.out.sqlserver.shared.*;
import com.franco.desco.application.property.PropertyCommands.*;
import com.franco.desco.application.property.port.out.PropertyPersistencePort;
import com.franco.desco.application.shared.*;
import com.franco.desco.application.shared.pagination.PageResult;
import com.franco.desco.domain.property.PropertyModels;
import org.springframework.jdbc.core.simple.SimpleJdbcCall;
import org.springframework.stereotype.Component;
import java.util.*;

@Component
public class PropertySqlServerAdapter implements PropertyPersistencePort {
    private final SqlServerPaExecutor executor; private final PaPayloadFactory payloadFactory;
    private final SimpleJdbcCall list,get,create,update,retire;
    public PropertySqlServerAdapter(SqlServerPaFactory f,SqlServerPaExecutor e,PaPayloadFactory p){executor=e;payloadFactory=p;list=f.callWithResultSets("prod","PA_Predio_Sel_Listado","items");get=f.callWithResultSets("prod","PA_Predio_Sel_DetalleCompleto","predio","titulares","versiones","parcelas","archivos");create=f.call("prod","PA_Predio_Ins_Registro");update=f.call("prod","PA_Predio_Upd_Registro");retire=f.call("prod","PA_Predio_Del_Registro");}

    public PersistenceResult<PageResult<PropertyModels.Summary>> list(ListProperties c,SessionIdentity i,RequestMetadata m){int page=c.page().pagina(),size=c.page().tamanio();Filter f=c.page().filtros();var filters=map("buscar",f==null?null:f.buscar(),"socioId",f==null?null:f.socioId(),"distritoCodigo",f==null?null:f.distritoCodigo(),"soloActivos",f==null?null:f.soloActivos(),"pagina",page,"tamanoPagina",size);var rs=executor.executeJsonMultiResult(list,payloadFactory.forQuery(i,m,Map.of("filtros",filters)));return PaAdapterSupport.page(rs.raw(),rs.rows("items"),page,size,this::summary,"No se pudieron consultar los predios.");}

    public PersistenceResult<PropertyModels.Detail> get(GetProperty c,SessionIdentity i,RequestMetadata m){var rs=executor.executeJsonMultiResult(get,payloadFactory.forQuery(i,m,Map.of("filtros",Map.of("predioId",c.predioId()))));if(!PaAdapterSupport.success(rs.raw()))return PersistenceResult.error(PaAdapterSupport.message(rs.raw(),"No se pudo consultar el predio."));var r=rs.one("predio").orElse(null);if(r==null)return PersistenceResult.error("El predio seleccionado no está disponible.");var owners=rs.rows("titulares").stream().map(x->new PropertyModels.Owner(SqlValues.longValue(x,"predio_titularidad_id"),SqlValues.longValue(x,"socio_id"),SqlValues.string(x,"tipo_documento"),SqlValues.string(x,"numero_documento"),SqlValues.string(x,"nombres"),SqlValues.string(x,"apellido_paterno"),SqlValues.string(x,"apellido_materno"),SqlValues.string(x,"tipo_titularidad"),SqlValues.decimal(x,"porcentaje"),SqlValues.localDate(x,"fecha_desde"),SqlValues.localDate(x,"fecha_hasta"),SqlValues.bool(x,"estado"))).toList();var versions=rs.rows("versiones").stream().map(x->new PropertyModels.Version(SqlValues.longValue(x,"predio_version_id"),SqlValues.decimal(x,"area_total_ha"),SqlValues.decimal(x,"area_cultivable_ha"),SqlValues.string(x,"tipo_riego"),SqlValues.string(x,"fuente_agua"),SqlValues.string(x,"infraestructura"),SqlValues.string(x,"observacion"),SqlValues.localDate(x,"fecha_desde"),SqlValues.localDate(x,"fecha_hasta"),SqlValues.bool(x,"estado"))).toList();var plots=rs.rows("parcelas").stream().map(x->new PropertyModels.Plot(SqlValues.longValue(x,"parcela_id"),SqlValues.string(x,"parcelaCodigo"),SqlValues.string(x,"parcelaNombre"),SqlValues.decimal(x,"area_ha"),SqlValues.bool(x,"parcelaEstado"),SqlValues.longValue(x,"ubicacion_id"),SqlValues.longValue(x,"parcela_cultivo_id"),SqlValues.longValue(x,"variedad_palta_id"),SqlValues.string(x,"variedad"),SqlValues.localDate(x,"fecha_inicio"),SqlValues.localDate(x,"fecha_fin"),SqlValues.string(x,"situacion_cultivo"),SqlValues.bool(x,"cultivoEstado"))).toList();var files=rs.rows("archivos").stream().map(x->new PropertyModels.FileRef(SqlValues.longValue(x,"archivo_id"),SqlValues.string(x,"nombre_original"),SqlValues.string(x,"mime_type"),SqlValues.string(x,"secure_url"),SqlValues.instant(x,"fecha_carga"),SqlValues.string(x,"categoria"),SqlValues.string(x,"origen_captura"))).toList();return PersistenceResult.ok(PaAdapterSupport.message(rs.raw(),"Predio consultado correctamente."),new PropertyModels.Detail(SqlValues.longValue(r,"predio_id"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.localDate(r,"fecha_registro"),SqlValues.bool(r,"estado"),SqlValues.longValue(r,"ubicacion_id"),SqlValues.string(r,"distrito_codigo"),SqlValues.longValue(r,"centro_poblado_id"),SqlValues.string(r,"referencia"),SqlValues.decimal(r,"latitud"),SqlValues.decimal(r,"longitud"),SqlValues.decimal(r,"altitud_m"),SqlValues.longValue(r,"predio_version_id"),SqlValues.decimal(r,"area_total_ha"),SqlValues.decimal(r,"area_cultivable_ha"),SqlValues.string(r,"tipo_riego"),SqlValues.string(r,"fuente_agua"),SqlValues.string(r,"infraestructura"),SqlValues.string(r,"observacion"),SqlValues.localDate(r,"fecha_desde"),owners,versions,plots,files));}

    public PersistenceResult<Long> create(CreateProperty c,SessionIdentity i,RequestMetadata m){var out=executor.executeJsonMutation(create,payloadFactory.forWrite(i,m,c,payload(c)));return PaAdapterSupport.result(out,SqlValues.longValue(out,"nPredioId"),"No se pudo registrar el predio.");}
    public PersistenceResult<Void> update(UpdateProperty c,SessionIdentity i,RequestMetadata m){var out=executor.executeJsonMutation(update,payloadFactory.forWrite(i,m,c,payload(c)));return PaAdapterSupport.result(out,null,"No se pudo actualizar el predio.");}
    public PersistenceResult<Void> retire(RetireProperty c,SessionIdentity i,RequestMetadata m){var out=executor.executeJsonMutation(retire,payloadFactory.forWrite(i,m,c,Map.of("predio",map("predioId",c.predioId(),"fechaRetiro",c.fechaRetiro(),"motivo",c.motivo()))));return PaAdapterSupport.result(out,null,"No se pudo retirar el predio.");}

    private Map<String,Object> payload(CreateProperty c){Map<String,Object> p=new LinkedHashMap<>();p.put("predio",map("codigo",c.codigo(),"nombre",c.nombre(),"fechaRegistro",c.fechaRegistro()));if(c.ubicacion()!=null)p.put("ubicacion",location(c.ubicacion()));if(c.caracteristicas()!=null)p.put("caracteristicas",characteristics(c.caracteristicas()));p.put("titulares",c.titulares().stream().map(this::owner).toList());return p;}
    private Map<String,Object> payload(UpdateProperty c){Map<String,Object> p=new LinkedHashMap<>();p.put("predio",map("predioId",c.predioId(),"codigo",c.codigo(),"nombre",c.nombre(),"fechaTitularidad",c.fechaTitularidad()));if(c.ubicacion()!=null)p.put("ubicacion",location(c.ubicacion()));if(c.caracteristicas()!=null)p.put("caracteristicas",characteristics(c.caracteristicas()));if(c.titulares()!=null)p.put("titulares",c.titulares().stream().map(this::owner).toList());return p;}
    private Map<String,Object> location(Location x){return map("distritoCodigo",x.distritoCodigo(),"centroPobladoId",x.centroPobladoId(),"referencia",x.referencia(),"latitud",x.latitud(),"longitud",x.longitud(),"altitudM",x.altitudM());}
    private Map<String,Object> characteristics(Characteristics x){return map("areaTotalHa",x.areaTotalHa(),"areaCultivableHa",x.areaCultivableHa(),"tipoRiego",x.tipoRiego(),"fuenteAgua",x.fuenteAgua(),"infraestructura",x.infraestructura(),"observacion",x.observacion(),"fechaDesde",x.fechaDesde());}
    private Map<String,Object> owner(Owner x){return map("socioId",x.socioId(),"tipoTitularidad",x.tipoTitularidad(),"porcentaje",x.porcentaje());}
    private PropertyModels.Summary summary(Map<String,Object> r){return new PropertyModels.Summary(SqlValues.longValue(r,"predio_id"),SqlValues.string(r,"codigo"),SqlValues.string(r,"nombre"),SqlValues.localDate(r,"fecha_registro"),SqlValues.bool(r,"estado"),SqlValues.string(r,"distrito_codigo"),SqlValues.longValue(r,"centro_poblado_id"),SqlValues.string(r,"referencia"),SqlValues.decimal(r,"area_total_ha"),SqlValues.decimal(r,"area_cultivable_ha"),SqlValues.string(r,"tipo_riego"),SqlValues.string(r,"titulares"));}
    private static Map<String,Object> map(Object...pairs){Map<String,Object>m=new LinkedHashMap<>();for(int x=0;x<pairs.length;x+=2)if(pairs[x+1]!=null)m.put((String)pairs[x],pairs[x+1]);return m;}
}
